face.layout_source:
// spectral-filter.face: the panel for tap/examples/spectral/spectral-filter.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/spectral/spectral-filter.face --meta <graph>.cragmeta

face "Spectral Filter" {
  row(gap = 10) {
    box "Band" { knob.big "Low" (low) knob.big "High" (high) }
    box "Shape" { knob "Tilt" (tilt) knob "Mix" (mix) }
    viz(grow = 1)
  }
}
